import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { OrderContext } from "./OrderContext"; // Importing OrderContext
import backgroundImage from "../Img/order5.jpg";

const AddOrder = () => {
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const { setOrdersChanged } = useContext(OrderContext); // Accessing setOrdersChanged from context
  const navigate = useNavigate();

  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  const sendData = (e) => {
    e.preventDefault();

    axios
      .post("http://localhost:5000/orders/", orderData)
      .then(() => {
        alert("Order Added");
        setOrderData({
          firstName: "",
          lastName: "",
          email: "",
          phoneNumber: "",
          address: "",
          city: "",
          orderId: "",
          specialInstructions: "",
          pickupTime: "",
          orderStatus: "",
        });

        // This will trigger a change in the context, causing AllOrders to update
        setOrdersChanged((prev) => !prev);

        navigate("/all-orders");
      })
      .catch((err) => {
        alert(err);
      });
  };

  const handleBackToHome = () => {
    navigate("/");
  };

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#f0f0f0",
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        backgroundBlendMode: "multiply",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.7)",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "100%",
          maxWidth: "600px",
          boxSizing: "border-box",
        }}
      >
        <h1 style={{ color: "#8B0000", fontWeight: "bold", textAlign: "center", marginBottom: "20px" }}>
          Add Order
        </h1>
        <form onSubmit={sendData} style={{ width: "100%" }}>
          {["firstName", "lastName", "email", "phoneNumber", "address", "city", "orderId", "specialInstructions", "pickupTime", "orderStatus"].map(
            (field) => (
              <div key={field} style={{ marginBottom: "15px" }}>
                <label htmlFor={field} style={{ fontWeight: "bold", color: "#333" }}>
                  {field.replace(/([A-Z])/g, " $1").toUpperCase()}
                </label>
                <input
                  type="text"
                  name={field}
                  id={field}
                  value={orderData[field]}
                  onChange={handleChange}
                  style={{
                    width: "100%",
                    padding: "8px",
                    borderRadius: "4px",
                    border: "1px solid #ccc",
                    fontSize: "16px",
                  }}
                  required
                />
              </div>
            )
          )}

          <div style={{ textAlign: "center" }}>
            <button
              type="submit"
              style={{
                padding: "12px 20px",
                backgroundColor: "#8B0000",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
                fontSize: "16px",
                width: "100%",
                marginBottom: "15px",
              }}
            >
              Add Order
            </button>
            <br />
            <button
              onClick={handleBackToHome}
              style={{
                padding: "12px 20px",
                backgroundColor: "#dc2626",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
                fontSize: "16px",
                width: "100%",
              }}
            >
              Back to Home
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddOrder;
